This Terraform configuration creates an Amazon Lightsail instance and provisions a static IPv4 address for it. The static IP is then attached to the Lightsail instance. The configuration uses the AWS provider in `us-east-1` and includes default variable values so it can be deployed directly.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the Lightsail resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "lightsail_instance_name" {
  description = "Name of the Amazon Lightsail instance."
  type        = string
  default     = "example-lightsail-instance"
}

variable "lightsail_static_ip_name" {
  description = "Name of the Lightsail static IPv4 address."
